/**
 * A footer with the brand, a tagline, groups of links and the copyright. Axes: layout (columns: brand above,
 * equal columns per group, row: the brand, the group names and the copyright in one row), signup mode (none,
 * first: a sign-up above the links), status mode (none, show: a live status pill), density. The live status
 * itself is a port contract.
 */
import { type ReactNode } from "react";
import { Block, Box, Button, Container, Form, Group, Input, Label, Stack, Text, Title } from "../compose";
import { FooterCard } from "../components/footer-card";
import { FooterColumns } from "../components/footer-columns";
import { MenuEntry } from "../components/menu-entry";
import { NavBlock } from "../components/nav-block";
import { Pill } from "../components/pill";
import { cn, tpl, uniqLabel } from "../utils";
import type { FooterSignup, FooterStatus } from "./sitemap-footer.types";
import type { MegaGroup } from "./mega-menu.types";

export type SitemapFooterProps = {
  label: string;
  brand: string;
  tagline: string;
  copyright: string;
  groups: MegaGroup[];
  signup?: FooterSignup;
  status?: FooterStatus;
  id?: string;
  layout?: "columns" | "row" | "card";
  density?: "default" | "compact";
  landmarkLabel?: string;
};

export function SitemapFooter({
  label,
  brand,
  tagline,
  copyright,
  groups,
  signup,
  status,
  id = "footer",
  layout = "columns",
  density = "default",
  landmarkLabel,
}: SitemapFooterProps) {
  return (
    <>
      {((layout as string) === "card") ? (
        <FooterCard label={label} brand={brand} groups={groups} landmarkLabel={landmarkLabel} />
      ) : (
        <Block
          tag="footer"
          className="mt-12 border-t border-border"
          data-layout={layout}
          aria-label={landmarkLabel}
          data-slot="site-footer"
        >
          <Container
            className={cn(
              "mx-auto w-full max-w-6xl px-4",
              "flex flex-col gap-8",
              (((density as string) === "compact") ? "py-6" : "py-12")
            )}
            data-slot="container"
          >
            {(signup?.mode === "first") ? (
              <Stack gap="4" className="max-w-md" data-slot="signup">
                <Title as={3} size="xl" weight="bold">
                  {signup?.title}
                </Title>
                <Form method="dialog" className={cn("w-full max-w-md", (false ? "mx-auto" : ""))} data-slot="email-form">
                  <Label htmlFor={tpl("{0}-email", id)} className="sr-only">
                    {signup?.label}
                  </Label>
                  <Group gap="2" align="start" className="w-full flex-wrap">
                    <Input type="email" name="email" className="min-w-0 flex-1" id={tpl("{0}-email", id)} data-slot="field" />
                    <Button variant="default" size="default" type="submit">
                      {signup?.submit}
                    </Button>
                  </Group>
                </Form>
              </Stack>
            ) : null}
            {((layout as string) === "columns") ? (
              <Box className="flex flex-col gap-8 md:flex-row md:items-start md:gap-12" data-slot="footer-top">
                <Stack gap="2" className="md:w-64 md:shrink-0">
                  <Text size="xl" weight="bold">
                    {brand}
                  </Text>
                  <Text size="sm" className="text-muted-foreground">
                    {tagline}
                  </Text>
                </Stack>
                <Box className="min-w-0 flex-1">
                  <FooterColumns label={label} groups={groups} landmarkLabel={landmarkLabel} />
                </Box>
              </Box>
            ) : (
              <Group gap="6" align="center" justify="between" className="flex-wrap">
                <Text size="base" weight="bold">
                  {brand}
                </Text>
                {((groups?.length ?? 0) > 0) ? (
                  <NavBlock label={(landmarkLabel ? uniqLabel(tpl("{0}, {1}", label, landmarkLabel)) : label)}>
                    <Group gap="4" className="flex-wrap">
                      {(groups ?? []).map((g) => (
                        <MenuEntry key={g.id} href={g.href} className="text-sm" testid="group">
                          {g.title}
                        </MenuEntry>
                      ))}
                    </Group>
                  </NavBlock>
                ) : null}
              </Group>
            )}
            <Group gap="4" align="center" justify="between" className="flex-wrap border-t border-border pt-6">
              <Text size="sm" className="text-muted-foreground">
                {copyright}
              </Text>
              {(status?.mode === "show") ? (
                <Pill tone="green" icon="circle-check">
                  {status?.label}
                </Pill>
              ) : null}
            </Group>
          </Container>
        </Block>
      )}
    </>
  );
}

